llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Ribavirin, a D-ribofuranosyl azole carboxamide closely matching the query's ribose and carboxamide, has an absolute oral bioavailability of 44.6% ± 2.1% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Viramidine, a D-ribofuranosyl azole with a polar amidine substituent, has 66.1% oral bioavailability in humans, showing that polar azole ribonucleosides can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fludarabine, a D-ribofuranosyl nucleoside with a polar purine base, has approximately 55% systemic availability after oral dosing, supporting that D-ribonucleosides can exceed 20% oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Levovirin, the L-ribose enantiomer of ribavirin, has <10% oral bioavailability in humans, but its L-stereochemistry makes it a poor model for the query's D-riboside.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Uridine, a very hydrophilic D-ribonucleoside, has ~7% oral bioavailability in humans, indicating that highly polar ribonucleosides can be poorly absorbed, though its uracil base is less structurally related to the query than ribavirin.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a D-ribofuranosyl azole carboxamide most closely related to ribavirin, whose human oral bioavailability is approximately 40-50%; the added ring hydroxyl increases polarity but does not outweigh the strong transferable evidence from ribavirin and other D-ribonucleosides, so F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The effect of the 5-hydroxyimidazole modification on transporter-mediated absorption relative to ribavirin is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

